	.B_img			(	w_B_img),
	.D_real			(	w_D_real_tmp),
	.D_img			(	w_D_img_tmp)
 );

/*****************<-------final output------->****************************/
multiplier multiplier16(
	.a				(	w_D_real_tmp),
	.b				(	w_D_img_tmp),
	//.ceabcd			(	1),
